const listQueue = `-- name: ListQueue :many
SELECT q.kind, q.item_id, q.title, q.owner_id, q.categories, q.city, q.waiting_since,
       COALESCE(NULLIF(b.name, ''), NULLIF(cp.name, ''), NULLIF(u.name, ''), '')::text AS owner_name,
       (l.moderator_id IS NOT NULL AND l.moderator_id = $1::bigint AND l.expires_at > $2::timestamptz)::boolean AS mine
FROM review_queue q
LEFT JOIN users u ON u.id = q.owner_id
LEFT JOIN business_profiles b ON b.user_id = q.owner_id AND q.kind IN ('task', 'task_revision')
LEFT JOIN creator_profiles cp ON cp.user_id = q.owner_id AND q.kind IN ('card', 'card_revision')
LEFT JOIN review_leases l ON l.kind = q.kind AND l.item_id = q.item_id
WHERE (cardinality($3::text[]) = 0 OR q.kind = ANY($3::text[]))
  AND (cardinality($4::text[]) = 0 OR q.categories && $4::text[])
  AND ($5::text = '' OR lower(q.city) = lower($5::text))
  AND ($6::timestamptz IS NULL OR q.waiting_since >= $6::timestamptz)
  AND ($7::timestamptz IS NULL OR q.waiting_since < $7::timestamptz)
  AND ($8::text = '' OR q.title ILIKE '%' || $8::text || '%' OR q.item_id = $8::text)
  AND (l.moderator_id IS NULL OR l.expires_at <= $2::timestamptz OR l.moderator_id = $1::bigint)
  AND NOT EXISTS (SELECT 1 FROM review_decisions d WHERE d.state = 'pending' AND d.kind = q.kind AND d.item_id::text = q.item_id)
ORDER BY CASE WHEN $9::boolean THEN q.waiting_since END DESC NULLS LAST, q.waiting_since ASC, q.kind, q.item_id
LIMIT $11 OFFSET $10
`

type ListQueueParams struct {
	Me         int64
	Now        pgtype.Timestamptz
	Kinds      []string
	Categories []string
	City       string
	Since      pgtype.Timestamptz
	Until      pgtype.Timestamptz
	Q          string
	Newest     bool
	Off        int32
	Lim        int32
}

type ListQueueRow struct {
	Kind         string
	ItemID       string
	Title        string
	OwnerID      int64
	Categories   []string
	City         string
	WaitingSince pgtype.Timestamptz
	OwnerName    string
	Mine         bool
}

// Очередь: без взятых другими (аренда не истекла) и без ждущих применения решений. Старые первыми (или новые).
func (q *Queries) ListQueue(ctx context.Context, arg ListQueueParams) ([]ListQueueRow, error) {
	rows, err := q.db.Query(ctx, listQueue,
		arg.Me,
		arg.Now,
		arg.Kinds,
		arg.Categories,
		arg.City,
		arg.Since,
		arg.Until,
		arg.Q,
		arg.Newest,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListQueueRow{}
	for rows.Next() {
		var i ListQueueRow
		if err := rows.Scan(
			&i.Kind,
			&i.ItemID,
			&i.Title,
			&i.OwnerID,
			&i.Categories,
			&i.City,
			&i.WaitingSince,
			&i.OwnerName,
			&i.Mine,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

