const tOTPFailure = `-- name: TOTPFailure :one
UPDATE staff_totp
SET failures = CASE WHEN failures + 1 >= $1::int THEN 0 ELSE failures + 1 END,
    locked_until = CASE WHEN failures + 1 >= $1::int THEN $2::timestamptz ELSE locked_until END,
    updated_at = now()
WHERE user_id = $3
RETURNING failures, locked_until
`

type TOTPFailureParams struct {
	MaxFailures int32
	LockUntil   pgtype.Timestamptz
	UserID      int64
}

type TOTPFailureRow struct {
	Failures    int32
	LockedUntil pgtype.Timestamptz
}

// Неверный код: счётчик; на пределе — блокировка до lock_until и счётчик заново.
func (q *Queries) TOTPFailure(ctx context.Context, arg TOTPFailureParams) (TOTPFailureRow, error) {
	row := q.db.QueryRow(ctx, tOTPFailure, arg.MaxFailures, arg.LockUntil, arg.UserID)
	var i TOTPFailureRow
	err := row.Scan(&i.Failures, &i.LockedUntil)
	return i, err
}

